 return {'measured_points':earned,'measured_maximum':maximum,'total_rubric_maximum':100,'overall_score_out_of_100':None,'unscored_points':100-maximum,'criteria':criteria,'unscored':[{'category':'Content quality and intent','points':20,'reason':'Independent page-level factual, intent, firsthand-experience and cannibalization review not complete; automation is not a quality score.'},{'category':'Performance and mobile experience','points':6,'reason':'No CrUX/field data. PageSpeed request returned HTTP 429; no Lighthouse or CWV score fabricated.'},{'category':'GEO readiness and measurement','points':6,'reason':'No measured answer-citation benchmark, Bing AI report or AI referral account export.'}],'target':'At least 64/68 measured readiness points, resolve critical/high issues, then assess the 32 unscored points.'}
